CREATE OR REPLACE FUNCTION public.ce_claim_specific_job_v1(p_job_id uuid, p_worker_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_cfg public.ce_automation_runtime;
  v_job public.ce_evaluation_job;
  v_global integer;
  v_bucket_running integer;
  v_interactive boolean;
begin
  LOCK TABLE public.c3_uat_conversation_scope IN SHARE MODE;
  perform pg_advisory_xact_lock(hashtextextended('ce-job-claim',0));
  select * into v_cfg from public.ce_automation_runtime where singleton=true;
  select * into v_job from public.ce_evaluation_job where id=p_job_id for update;
  if v_job.id is null then return jsonb_build_object('result','not_found'); end if;
  if NOT public.ce_conversation_evaluable_v1(v_job.conversation_id) then return jsonb_build_object('result','conversation_not_evaluable'); end if;
  if v_job.company_id IS DISTINCT FROM public.ce_runtime_conversation_company(v_job.conversation_id) then return jsonb_build_object('result','tenant_mismatch'); end if;
  perform public.ce_reap_expired_jobs_v1();
  select * into v_job from public.ce_evaluation_job where id=p_job_id for update;
  if v_job.status='running' then return jsonb_build_object('result','already_running','job_id',v_job.id); end if;
  v_interactive := v_job.source in ('manual','ce_dwell','resolved','verified_correction');
  if not coalesce(v_cfg.enabled,false) and not v_interactive then return jsonb_build_object('result','disabled'); end if;
  if v_job.status<>'queued' or v_job.available_at>now() then return jsonb_build_object('result','not_claimable','status',v_job.status); end if;
  select count(*) into v_global from public.ce_evaluation_job where status='running' AND NOT public.c3_uat_learning_excluded(conversation_id);
  if v_global>=v_cfg.global_concurrency then return jsonb_build_object('result','global_busy'); end if;
  select count(*) into v_bucket_running from public.ce_evaluation_job j where j.status='running' and NOT public.c3_uat_learning_excluded(j.conversation_id) and coalesce(j.company_id::text,'__preactivation__')=coalesce(v_job.company_id::text,'__preactivation__');
  if v_bucket_running>=v_cfg.per_company_concurrency then return jsonb_build_object('result','company_busy'); end if;
  update public.ce_evaluation_job set status='running',lease_owner=p_worker_id,lease_expires_at=now()+interval '10 minutes',started_at=coalesce(started_at,now()),attempts=attempts+1,error_code=null,updated_at=now() where id=p_job_id;
  return jsonb_build_object('result','claimed','job_id',p_job_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.ce_dispatch_realtime_evaluation_v1(p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_enqueue jsonb;
  v_job_id uuid;
  v_cfg public.ce_automation_runtime;
  v_token text;
  v_request_id bigint;
begin
  v_enqueue := public.ce_enqueue_current_snapshot_v1(p_conversation_id,'ce_dwell',now());
  if coalesce(v_enqueue->>'result','') not in ('queued','already_queued') then
    return v_enqueue;
  end if;
  v_job_id := nullif(v_enqueue->>'job_id','')::uuid;
  if v_job_id is null then return jsonb_build_object('result','job_id_missing'); end if;
  select * into v_cfg from public.ce_automation_runtime where singleton=true;
  if nullif(trim(coalesce(v_cfg.worker_url,'')),'') is null or v_cfg.worker_secret_id is null then
    return jsonb_build_object('result','worker_not_configured','job_id',v_job_id);
  end if;
  select ds.decrypted_secret into v_token from vault.decrypted_secrets ds where ds.id=v_cfg.worker_secret_id;
  if nullif(coalesce(v_token,''),'') is null then return jsonb_build_object('result','worker_token_missing','job_id',v_job_id); end if;
  select net.http_post(
    url:=v_cfg.worker_url,
    headers:=jsonb_build_object('Content-Type','application/json','X-CE-Worker-Token',v_token),
    body:=jsonb_build_object('source','realtime','job_id',v_job_id),
    timeout_milliseconds:=5000
  ) into v_request_id;
  return jsonb_build_object('result','dispatched','job_id',v_job_id,'request_id',v_request_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.ce_realtime_assistant_message_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.role='assistant' and coalesce(new.is_recalled,false)=false and coalesce(new.content,'')<>'__THINKING__' then
    perform public.ce_dispatch_realtime_evaluation_v1(new.conversation_id);
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.commit_ai_reply_tx(p_conversation_id uuid, p_source_message_id uuid, p_content text, p_metadata jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_conv record;
  v_source record;
  v_state record;
  v_state_found boolean := false;
  v_authorized_revision bigint;
  v_response_hash text;
  v_existing record;
  v_message_id uuid;
  v_now timestamptz := now();
BEGIN
  IF p_content IS NULL OR btrim(p_content) = '' OR p_content = '__THINKING__' OR length(p_content) > 4000 THEN
    RETURN jsonb_build_object('result', 'invalid_content');
  END IF;

  SELECT id, company_id, status, assigned_agent_id
    INTO v_conv
    FROM public.conversations
   WHERE id = p_conversation_id
   FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('result', 'not_found'); END IF;

  IF v_conv.status IN ('resolved', 'closed') THEN
    DELETE FROM public.messages
     WHERE conversation_id = p_conversation_id
       AND content = '__THINKING__'
       AND COALESCE(metadata->>'source_message_id', '') = p_source_message_id::text;
    RETURN jsonb_build_object('result', 'resolved');
  END IF;

  IF v_conv.assigned_agent_id IS NOT NULL
     OR v_conv.status IN ('pending', 'transferred', 'human_needed', 'human_control', 'escalation_risk', 'unresolved') THEN
    DELETE FROM public.messages
     WHERE conversation_id = p_conversation_id
       AND content = '__THINKING__'
       AND COALESCE(metadata->>'source_message_id', '') = p_source_message_id::text;
    RETURN jsonb_build_object('result', 'human_control');
  END IF;

  SELECT id, conversation_id, role, is_recalled, created_at
    INTO v_source
    FROM public.messages
   WHERE id = p_source_message_id
   FOR SHARE;
  IF NOT FOUND
     OR v_source.conversation_id IS DISTINCT FROM p_conversation_id
     OR v_source.role IS DISTINCT FROM 'visitor'
     OR v_source.is_recalled IS TRUE THEN
    DELETE FROM public.messages
     WHERE conversation_id = p_conversation_id
       AND content = '__THINKING__'
       AND COALESCE(metadata->>'source_message_id', '') = p_source_message_id::text;
    RETURN jsonb_build_object('result', 'invalid_source_message');
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.handoff_event h
     WHERE h.conversation_id = p_conversation_id
       AND h.handoff_type = 'agent_to_agent'
       AND h.created_at >= v_source.created_at
  ) THEN
    DELETE FROM public.messages
     WHERE conversation_id = p_conversation_id
       AND content = '__THINKING__'
       AND COALESCE(metadata->>'source_message_id', '') = p_source_message_id::text;
    RETURN jsonb_build_object('result', 'superseded_source');
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.messages newer
     WHERE newer.conversation_id = p_conversation_id
       AND newer.role = 'visitor'
       AND newer.is_recalled = false
       AND newer.content <> '__THINKING__'
       AND (
         newer.created_at > v_source.created_at
         OR (newer.created_at = v_source.created_at AND newer.id > v_source.id)
       )
  ) THEN
    DELETE FROM public.messages
     WHERE conversation_id = p_conversation_id
       AND content = '__THINKING__'
       AND COALESCE(metadata->>'source_message_id', '') = p_source_message_id::text;
    RETURN jsonb_build_object('result', 'superseded_source');
  END IF;

  SELECT company_id, revision, source_message_id INTO v_state
    FROM public.conversation_commerce_state
   WHERE conversation_id = p_conversation_id FOR SHARE;
  v_state_found := FOUND;
  IF v_state_found AND v_state.company_id IS DISTINCT FROM v_conv.company_id THEN
    RETURN jsonb_build_object('result','tenant_mismatch');
  END IF;
  IF (v_state_found AND v_state.source_message_id = p_source_message_id)
      OR COALESCE(p_metadata ? 'b2_expected_revision',false) THEN
    IF p_metadata IS NULL
       OR jsonb_typeof(p_metadata->'b2_expected_revision') <> 'number'
       OR COALESCE(p_metadata->>'b2_expected_revision','') !~ '^[0-9]+$'
       OR length(COALESCE(p_metadata->>'b2_expected_revision','')) > 18
       OR p_metadata->>'b2_expected_company_id' IS DISTINCT FROM v_conv.company_id::text
       OR p_metadata->>'b2_source_message_id' IS DISTINCT FROM p_source_message_id::text
       OR p_metadata->>'b2_gate_contract' IS DISTINCT FROM 'executeB2PersistenceGate:allow_after_revalidation'
       OR p_metadata->>'b2_commit_source' IS DISTINCT FROM 'commit_ai_reply_tx'
       OR COALESCE(p_metadata->>'b2_response_hash','') !~ '^[0-9a-f]{64}$'
       OR COALESCE(p_metadata->>'b2_idempotency_key','') !~ '^[0-9a-f]{64}$' THEN
      RETURN jsonb_build_object('result','invalid_b2_revision_proof');
    END IF;
    v_authorized_revision := (p_metadata->>'b2_expected_revision')::bigint;
    v_response_hash := encode(extensions.digest(convert_to(p_content,'UTF8'),'sha256'),'hex');
    IF p_metadata->>'b2_response_hash' IS DISTINCT FROM v_response_hash
       OR p_metadata->>'b2_idempotency_key' IS DISTINCT FROM
         encode(extensions.digest(convert_to(
           v_conv.company_id::text || ':' || p_conversation_id::text || ':' ||
           p_source_message_id::text || ':' || v_authorized_revision::text ||
           ':' || v_response_hash, 'UTF8'), 'sha256'),'hex') THEN
      RETURN jsonb_build_object('result','response_hash_mismatch');
    END IF;
    IF v_authorized_revision IS DISTINCT FROM
       (CASE WHEN v_state_found THEN v_state.revision ELSE 0 END) THEN
      RETURN jsonb_build_object('result','stale_authorized_revision',
        'authorized_revision',v_authorized_revision,
        'current_revision', CASE WHEN v_state_found THEN v_state.revision ELSE 0 END);
    END IF;
  END IF;

  SELECT id, content, metadata
    INTO v_existing
    FROM public.messages
   WHERE conversation_id = p_conversation_id
     AND role = 'assistant'
     AND is_recalled = false
     AND COALESCE(metadata->>'source_message_id', '') = p_source_message_id::text
     AND content <> '__THINKING__'
   ORDER BY created_at ASC, id ASC
   LIMIT 1;
  IF FOUND THEN
    DELETE FROM public.messages
     WHERE conversation_id = p_conversation_id
       AND content = '__THINKING__'
       AND COALESCE(metadata->>'source_message_id', '') = p_source_message_id::text;
    IF v_existing.content = p_content AND (
       NOT COALESCE(p_metadata ? 'b2_expected_revision', false) OR
       (v_existing.metadata->>'b2_response_hash' = p_metadata->>'b2_response_hash'
        AND v_existing.metadata->>'b2_idempotency_key' = p_metadata->>'b2_idempotency_key')
    ) THEN
      RETURN jsonb_build_object('result', 'idempotent', 'message_id', v_existing.id);
    END IF;
    RETURN jsonb_build_object('result', 'response_substitution', 'message_id', v_existing.id);
  END IF;

  DELETE FROM public.messages
   WHERE conversation_id = p_conversation_id
     AND content = '__THINKING__'
     AND COALESCE(metadata->>'source_message_id', '') = p_source_message_id::text;

  INSERT INTO public.messages(conversation_id, role, content, status, is_recalled, metadata)
  VALUES (
    p_conversation_id, 'assistant', p_content, 'delivered', false,
    COALESCE(p_metadata, '{}'::jsonb)
      || jsonb_build_object('source_message_id', p_source_message_id::text, 'control_commit', 'ai')
  ) RETURNING id INTO v_message_id;

  UPDATE public.conversations SET updated_at = v_now WHERE id = p_conversation_id;
  RETURN jsonb_build_object('result', 'success', 'message_id', v_message_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.receive_widget_message_tx(p_conversation_id uuid, p_session_token text, p_content text, p_client_message_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_conv record; v_session record; v_message_id uuid; v_thinking_id uuid;
  v_human_control boolean; v_now timestamptz:=now(); v_client_id text;
begin
  if p_conversation_id is null or p_session_token is null or length(p_session_token)<32 or length(p_session_token)>256 or p_content is null or btrim(p_content)='' or length(btrim(p_content))>2000 then
    return jsonb_build_object('result','invalid_input');
  end if;
  v_client_id:=nullif(btrim(coalesce(p_client_message_id,'')),'');
  if v_client_id is not null and v_client_id !~ '^[0-9a-fA-F-]{36}$' then return jsonb_build_object('result','invalid_client_message_id'); end if;

  select vs.id,vs.channel_config_id,vs.visitor_metadata->>'origin' as origin into v_session
  from public.visitor_session vs where vs.session_token=p_session_token limit 1;
  if not found then return jsonb_build_object('result','invalid_session'); end if;

  select c.id,c.status,c.assigned_agent_id,c.visitor_session_id,c.channel_config_id into v_conv
  from public.conversations c where c.id=p_conversation_id for update;
  if not found or v_conv.visitor_session_id is distinct from v_session.id or v_conv.channel_config_id is distinct from v_session.channel_config_id then
    return jsonb_build_object('result','not_found');
  end if;
  if v_conv.status in ('resolved','closed') then return jsonb_build_object('result','resolved'); end if;

  if v_client_id is not null then
    select id into v_message_id from public.messages
    where conversation_id=p_conversation_id and role='visitor' and coalesce(is_recalled,false)=false
      and metadata->>'client_message_id'=v_client_id limit 1;
    if found then
      return jsonb_build_object('result','idempotent','message_id',v_message_id,'ai_reply_pending',
        exists(select 1 from public.messages where conversation_id=p_conversation_id and content='__THINKING__'
          and metadata->>'source_message_id'=v_message_id::text and coalesce(is_recalled,false)=false));
    end if;
  end if;

  v_human_control:=v_conv.assigned_agent_id is not null or v_conv.status in (
    'pending','transferred','human_needed','human_control','escalation_risk','unresolved'
  );

  insert into public.messages(conversation_id,role,content,status,is_recalled,metadata)
  values(p_conversation_id,'visitor',btrim(p_content),'delivered',false,
    case when v_client_id is null then '{}'::jsonb else jsonb_build_object('client_message_id',v_client_id) end)
  returning id into v_message_id;
  update public.visitor_session set last_seen_at=v_now where id=v_session.id;
  update public.conversations set updated_at=v_now where id=p_conversation_id;

  if v_human_control then return jsonb_build_object('result','human_control','message_id',v_message_id); end if;

  insert into public.messages(conversation_id,role,content,status,is_recalled,metadata)
  values(p_conversation_id,'assistant','__THINKING__','sending',false,
    jsonb_build_object('source_message_id',v_message_id::text,'control_claim','ai'))
  returning id into v_thinking_id;
  return jsonb_build_object('result','success','message_id',v_message_id,'thinking_message_id',v_thinking_id);
exception when unique_violation then
  if v_client_id is not null then
    select id into v_message_id from public.messages where conversation_id=p_conversation_id and role='visitor'
      and metadata->>'client_message_id'=v_client_id limit 1;
    return jsonb_build_object('result','idempotent','message_id',v_message_id);
  end if;
  raise;
end;
$function$
